#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 撑杆跳僵尸：
    /// - 生成时自带 1 根撑杆（最多同时持有 3 根），只要持有撑杆就进入 2 倍疾跑。
    /// - 遇到器械时不啃食，先原地播 12 帧起跳预备（跳跃动画的蹬地前段），
    ///   蹬地帧手上撑杆隐藏（手上的杆已插进身前地面）、向前上方跃起。
    /// - 正常越过落地后，背上的撑杆切回手上（手上按剩余数量重新显示），
    ///   一根地上撑杆留在起跳点；每个撑杆都能进行跳跃一次。
    /// - 若跳跃中被足够高的器械挡住（照骷髅马速度清零坠回），本次跳跃不消耗撑杆、不留下杆。
    /// - 杆用完恢复 1 倍普僵；附近有地上的撑杆时会自动吸取（上限内，刚落地的杆有 1 秒冷却）。
    /// - 跳跃轨迹照抄骷髅马（向前上方的抛物线初速度，之后交给重力引擎）。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.poleVaultingZombie)]
    public class PoleVaultingZombie : AIEntityBehaviour
    {
        public PoleVaultingZombie(string nsp, string name) : base(nsp, name)
        {
        }

        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetJumpState(entity, JUMP_STATE_NONE);
            SetPoleCount(entity, START_POLE_COUNT);
            SetPrepareTimer(entity, new FrameTimer(JUMP_PREPARE_TICKS));
            SetAirTimer(entity, new FrameTimer(JUMP_MIN_AIR_TICKS));
            UpdatePoleVisuals(entity);
            UpdateSpeed(entity);
            Debug.Log($"[PoleDebug] {entity} init, poleCount={GetPoleCount(entity)}");
        }

        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            // 起跳两段式：先进入起跳预备（原地播跳跃动画的前段），播到蹬地帧才真正跳起
            if (entity.State == STATE_JUMP && GetJumpState(entity) == JUMP_STATE_NONE)
            {
                Debug.Log($"[PoleDebug] {entity} jump trigger: state={entity.State} jumpState={GetJumpState(entity)} count={GetPoleCount(entity)}");
                SetJumpState(entity, JUMP_STATE_PREPARE);
                GetPrepareTimer(entity)?.Reset();
            }
            else if (entity.State == STATE_JUMP && GetJumpState(entity) == JUMP_STATE_PREPARE)
            {
                var prepareTimer = GetPrepareTimer(entity);
                if (prepareTimer != null && prepareTimer.Expired)
                {
                    // 蹬地帧：手上的杆插进身前地面（隐藏），向前上方蹬出一跳（数值照抄骷髅马的跳跃）
                    TakeOff(entity);
                }
            }
        }

        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            var jumpState = GetJumpState(entity);
            // 各阶段只驱动自己的计时器：预备期跑预备倒计时，飞行期跑滞空保护倒计时
            if (jumpState == JUMP_STATE_PREPARE)
            {
                GetPrepareTimer(entity)?.Run();
            }
            else if (jumpState == JUMP_STATE_JUMPING)
            {
                GetAirTimer(entity)?.Run();
            }
            if (jumpState == JUMP_STATE_JUMPING && entity.State == STATE_JUMP)
            {
                // 跳跃中被足够高的器械挡住：标记本次跳跃被阻挡，速度清零坠回地面（照骷髅马）
                if (blocksJumpDetector.DetectExists(entity))
                {
                    SetJumpBlocked(entity, true);
                    var vel = entity.Velocity;
                    vel.x = 0;
                    vel.y = 0;
                    entity.Velocity = vel;
                }
                // 兜底落地结算：被重力板等外力按回地面时接触回调可能不再触发，
                // 只要已落回地面且飞满最小时间，同样完成落地结算（与落地回调幂等）
                var airTimer = GetAirTimer(entity);
                if (entity.IsOnGround && (airTimer == null || airTimer.Expired))
                {
                    FinishJump(entity);
                }
            }
            PickupUpdate(entity);
        }

        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            if (entity.State == STATE_JUMP && GetJumpState(entity) == JUMP_STATE_JUMPING)
            {
                // 刚起跳还在地面时的接触回调不算落地，只有飞满最小时间后的接触才视为落地
                var airTimer = GetAirTimer(entity);
                if (airTimer != null && !airTimer.Expired)
                    return;
                FinishJump(entity);
            }
        }

        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            SetJumpState(entity, JUMP_STATE_NONE);
        }

        // 供状态行为询问的接口：
        public static bool IsJumping(Entity entity) => GetJumpState(entity) != JUMP_STATE_NONE;
        public static bool ShouldJump(Entity entity) =>
            !entity.IsDead
            && GetPoleCount(entity) > 0
            && entity.State == STATE_WALK
            && EnemyMeleeBehaviour.HasMeleeTarget(entity);

        // 蹬地：扣下一根撑杆并实际放在起跳点（生成地上撑杆），
        // 手上的杆隐藏（已插进身前地面）、背上的杆数量刷新，然后腾空。
        private static void TakeOff(Entity entity)
        {
            var count = GetPoleCount(entity);
            if (count <= 0)
            {
                // 极端情况兜底：没杆可跳则取消起跳，回到正常状态
                SetJumpState(entity, JUMP_STATE_NONE);
                return;
            }
            SetPoleCount(entity, count - 1);

            var position = entity.Position;
            position.y = entity.Level.GetGroundY(position.x, position.z);
            SetJumpStartPosition(entity, position);
            SetJumpBlocked(entity, false);

            // 撑杆在实际起跳时就被放下，留在起跳点
            var spawnParams = entity.GetSpawnParams();
            var spawned = entity.Level.Spawn(VanillaEnemyID.pole, position, entity, spawnParams);
            spawned?.SetProperty(PoleEntity.PROP_PICKUP_COOLDOWN, (int)PICKUP_COOLDOWN_TICKS);
            SetLastLeftPole(entity, spawned == null ? null : new EntityID(spawned));
            Debug.Log($"[PoleDebug] {entity} takeoff, pole spawned={(spawned != null ? spawned.ID.ToString() : "FAILED")} at {position}");

            entity.SetModelProperty(PROP_POLE_VISIBLE, false);
            UpdateBackPoleVisuals(entity);

            var airTimer = GetAirTimer(entity);
            airTimer?.Reset();
            var vel = entity.Velocity;
            vel.x = entity.GetFacingX() * JUMP_FORWARD_SPEED;
            vel.y = JUMP_UP_SPEED;
            entity.Velocity = vel;
            SetJumpState(entity, JUMP_STATE_JUMPING);
        }

        // 落地结算：正常越过则撑杆已留在起跳点，无需处理；
        // 被高器械挡回则刚放下的撑杆直接消失（不退回身上，也不留在地上）。
        // 结算完成后背上的撑杆切回手上（手上按剩余数量重新显示）。
        private static void FinishJump(Entity entity)
        {
            SetJumpState(entity, JUMP_STATE_NONE);
            if (GetJumpBlocked(entity))
            {
                var poleId = GetLastLeftPole(entity);
                if (poleId != null && poleId.Exists(entity.Level))
                {
                    poleId.GetEntity(entity.Level)?.Remove();
                }
                Debug.Log($"[PoleDebug] {entity} landed blocked, pole destroyed");
            }
            SetLastLeftPole(entity, null);
            SetJumpBlocked(entity, false);
            UpdatePoleVisuals(entity);
            UpdateSpeed(entity);
        }

        // 自动吸取附近地上的撑杆（地雷 TNT 碰撞盒同款范围）
        private static void PickupUpdate(Entity entity)
        {
            if (entity.IsDead)
                return;
            if (GetPoleCount(entity) >= POLE_COUNT_MAX)
                return;
            var pole = pickupDetector.DetectEntityWithTheLeast(
                entity,
                (self, target) => (target.Position - self.Position).sqrMagnitude
            );
            if (pole == null)
                return;
            pole.Remove();

            SetPoleCount(entity, GetPoleCount(entity) + 1);
            UpdatePoleVisuals(entity);
            UpdateSpeed(entity);
        }

        // 撑杆三处显示：手上的杆、背上的两根，按持有数量依次点亮
        private static void UpdatePoleVisuals(Entity entity)
        {
            var count = GetPoleCount(entity);
            entity.SetModelProperty(PROP_POLE_VISIBLE, count >= 1);
            entity.SetModelProperty(PROP_POLE1_VISIBLE, count >= 2);
            entity.SetModelProperty(PROP_POLE2_VISIBLE, count >= 3);
        }

        // 背上两根撑杆的显示（蹬地后手上已隐藏，背上的数量保持不变）
        private static void UpdateBackPoleVisuals(Entity entity)
        {
            var count = GetPoleCount(entity);
            entity.SetModelProperty(PROP_POLE1_VISIBLE, count >= 2);
            entity.SetModelProperty(PROP_POLE2_VISIBLE, count >= 3);
        }

        private static void UpdateSpeed(Entity entity)
        {
            SetSpeed(entity, GetPoleCount(entity) > 0 ? SPEED_SPRINT : SPEED_AFTER_VAULT);
        }

        // 设置移速：写入速度属性，并把身上可能存在的“随机速度 buff”固定成 1 倍，
        // 保证 2 倍冲刺 / 1 倍恢复不被随机数干扰。
        private static void SetSpeed(Entity entity, float speed)
        {
            entity.SetProperty(VanillaEnemyProps.SPEED, speed);
            foreach (var buff in entity.GetBuffs<RandomEnemySpeedBuff>())
            {
                RandomEnemySpeedBuff.SetSpeed(buff, 1);
            }
        }

        private static readonly Detector pickupDetector = new PolePickupDetector();

        // 跳跃中被足够高的器械挡住（照骷髅马：撞上则速度清零坠回地面）
        private static readonly Detector blocksJumpDetector = new SkeletonHorseBlocksJumpDetector();

        private class PolePickupDetector : Detector
        {
            public PolePickupDetector()
            {
                factionTarget = FactionTarget.Any;
                canDetectInvisible = true;
                // 地上撑杆自身带有 not_target 标记（不被器械索敌），拾取检测需要显式放行
                canDetectNoTarget = true;
            }
            // 吸取范围与地雷 TNT 的碰撞盒同款尺寸
            protected override Bounds GetDetectionBounds(Entity self)
            {
                return new Bounds(self.Position, new Vector3(PICKUP_RANGE_X, PICKUP_RANGE_Y, PICKUP_RANGE_Z));
            }
            public override bool ValidateTarget(DetectionParams self, Entity target)
            {
                return base.ValidateTarget(self, target)
                    && target.IsEntityOf(VanillaEnemyID.pole)
                    // 拾取冷却中的杆（刚被丢弃的）不进入候选
                    && target.GetProperty<int>(PoleEntity.PROP_PICKUP_COOLDOWN) <= 0;
            }
        }

        public const int STATE_JUMP = VanillaEnemyStates.POLE_VAULTING_JUMP;
        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int JUMP_STATE_NONE = 0;
        public const int JUMP_STATE_PREPARE = 2;      // 起跳预备：原地播放跳跃动画的前段，蹬地帧（12 帧）后才真正跳起
        public const int JUMP_STATE_JUMPING = 1;
        public const int POLE_ARM_IDLE = 10001;       // 手臂层：持杆待机（ArmState 参数值）
        public const int POLE_ARM_JUMP = 10002;       // 手臂层：撑杆跳跃（ArmState 参数值）
        public const int JUMP_PREPARE_TICKS = 6;     // 起跳预备时长：跳跃动画播到 12 帧（蹬地帧）后起跳
        public const int JUMP_MIN_AIR_TICKS = 10;     // 起跳后的最小滞空时间：期间不算落地
        public const int START_POLE_COUNT = 1;        // 生成时自带 1 根撑杆
        public const int POLE_COUNT_MAX = 3;          // 最多同时持有 3 根
        public const float SPEED_SPRINT = 2f;         // 有杆时的疾跑移速：2 倍普僵
        public const float SPEED_AFTER_VAULT = 1f;    // 杆用完后的移速：恢复 1 倍普僵
        public const float JUMP_FORWARD_SPEED = 5f;   // 起跳向前速度（照抄骷髅马）
        public const float JUMP_UP_SPEED = 12f;       // 起跳向上速度（照抄骷髅马）
        public const float PICKUP_RANGE_X = 48f;      // 吸取范围：地雷 TNT 碰撞盒同款
        public const float PICKUP_RANGE_Y = 24f;
        public const float PICKUP_RANGE_Z = 48f;
        public const float PICKUP_COOLDOWN_TICKS = 30f; // 刚落地的杆的拾取冷却：1 秒
        public const string PROP_POLE_VISIBLE = "PoleVisible";
        public const string PROP_POLE1_VISIBLE = "Pole1Visible";
        public const string PROP_POLE2_VISIBLE = "Pole2Visible";
        public static readonly VanillaEntityPropertyMeta<int> FIELD_JUMP_STATE = new VanillaEntityPropertyMeta<int>("PoleJumpState");
        public static readonly VanillaEntityPropertyMeta<int> FIELD_POLE_COUNT = new VanillaEntityPropertyMeta<int>("PoleCount");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> FIELD_AIR_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("PoleAirTimer");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> FIELD_PREPARE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("PolePrepareTimer");
        public static readonly VanillaEntityPropertyMeta<Vector3> FIELD_JUMP_START_POSITION = new VanillaEntityPropertyMeta<Vector3>("PoleJumpStartPosition");
        public static readonly VanillaEntityPropertyMeta<bool> FIELD_JUMP_BLOCKED = new VanillaEntityPropertyMeta<bool>("PoleJumpBlocked");
        public static readonly VanillaEntityPropertyMeta<EntityID> FIELD_LAST_LEFT_POLE = new VanillaEntityPropertyMeta<EntityID>("PoleLastLeft");

        public static int GetJumpState(Entity entity) => entity.GetBehaviourField<int>(FIELD_JUMP_STATE);
        public static void SetJumpState(Entity entity, int value) => entity.SetBehaviourField(FIELD_JUMP_STATE, value);

        public static int GetPoleCount(Entity entity) => entity.GetBehaviourField<int>(FIELD_POLE_COUNT);
        public static void SetPoleCount(Entity entity, int value) => entity.SetBehaviourField(FIELD_POLE_COUNT, value);

        public static FrameTimer? GetAirTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(FIELD_AIR_TIMER);
        public static void SetAirTimer(Entity entity, FrameTimer? value) => entity.SetBehaviourField(FIELD_AIR_TIMER, value);

        public static FrameTimer? GetPrepareTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(FIELD_PREPARE_TIMER);
        public static void SetPrepareTimer(Entity entity, FrameTimer? value) => entity.SetBehaviourField(FIELD_PREPARE_TIMER, value);

        public static Vector3 GetJumpStartPosition(Entity entity) => entity.GetBehaviourField<Vector3>(FIELD_JUMP_START_POSITION);
        public static void SetJumpStartPosition(Entity entity, Vector3 value) => entity.SetBehaviourField(FIELD_JUMP_START_POSITION, value);

        public static bool GetJumpBlocked(Entity entity) => entity.GetBehaviourField<bool>(FIELD_JUMP_BLOCKED);
        public static void SetJumpBlocked(Entity entity, bool value) => entity.SetBehaviourField(FIELD_JUMP_BLOCKED, value);

        public static EntityID? GetLastLeftPole(Entity entity) => entity.GetBehaviourField<EntityID>(FIELD_LAST_LEFT_POLE);
        public static void SetLastLeftPole(Entity entity, EntityID? value) => entity.SetBehaviourField(FIELD_LAST_LEFT_POLE, value);
    }
}
